    표5_매튜헨리: [
        {"영어원문":"They call God the heart-knower — for he only can tell which of the two is the more fit for this office.", "한국어번역":"그들은 하나님을 심령을 아시는 분으로 불렀다 — 왜냐하면 오직 그분만이 두 사람 중 누가 이 직무에 더 적합한지 말씀하실 수 있기 때문이다.", "핵심통찰":"인간이 판단할 수 없는 것을 하나님께 맡기는 것이 지혜이다"},
        {"영어원문":"Show whether of these two thou hast chosen — they did not presume to choose themselves, but referred it to God.", "한국어번역":"이 두 사람 중 누구를 택하셨는지 보이소서 — 그들은 스스로 선택하려 하지 않고 하나님께 맡겼다.", "핵심통찰":"사역자 선택에서 하나님의 주권을 인정하는 것이 겸손이다"},
        {"영어원문":"Prayer before the lot — they did not trust the lot without prayer; the lot was accompanied with prayer.", "한국어번역":"제비 전에 기도 — 그들은 기도 없이 제비를 신뢰하지 않았다. 제비는 기도와 함께 이루어졌다.", "핵심통찰":"어떤 방법을 사용하든 기도가 먼저여야 한다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"마음을 아시는 주여 — 하나님께 결정을 위탁하는 기도", "예화_적용":"인간의 판단 능력의 한계를 인정하고 마음을 아시는 하나님께 맡기는 기도이다"},
        {"대지":"서론", "내용":"인사 담당자가 가장 힘든 일이 무엇인지 묻는다면 '사람을 아는 것'이라고 할 것이다. 이력서와 면접으로는 그 사람의 진짜 마음을 알 수 없다. 그래서 사도들은 하나님께 기도했다. '뭇 사람의 마음을 아시는 주여.' 마음을 아시는 분이 선택하셔야 한다", "예화_적용":"X-ray가 보이지 않는 내부를 보여주듯, 하나님은 인간의 마음 깊은 곳을 보신다"},
        {"대지":"1대지: 뭇 사람의 마음을 아시는 주여 (전지하신 하나님)", "내용":"하나님만이 마음 깊은 곳을 아신다. 외면은 비슷해 보여도 내면은 다르다. 그래서 하나님의 선택이 필요하다. 우리는 외모를 보지만 하나님은 중심을 보신다(삼상 16:7)", "예화_적용":"성분 분석기는 육안으로 보이지 않는 것을 분석한다. 하나님은 영혼의 성분을 아신다"},
        {"대지":"2대지: 이 두 사람 중에 (구체적 기도)", "내용":"기도는 구체적이어야 한다. '이 두 사람 중에'라고 구체적으로 요청했다. 막연한 기도가 아닌 구체적인 요청이다. 하나님께 구체적으로 기도하는 것이 신앙이다", "예화_적용":"의사에게 어디가 아픈지 정확히 말해야 처방을 받을 수 있다. 기도도 구체적이어야 응답이 온다"},
        {"대지":"3대지: 택하신 바 되었는지를 보이시옵소서 (위탁의 기도)", "내용":"'택하신 바 되었는지'는 이미 선택이 하나님께 있음을 인정하는 것이다. 우리가 선택하는 것이 아니라 하나님의 선택을 발견하는 것이다. 이것이 진정한 기도의 태도이다", "예화_적용":"금맥을 찾는 광부가 금을 만드는 것이 아니라 이미 있는 금을 발견하듯, 기도는 하나님의 뜻을 만드는 것이 아니라 발견하는 것이다"},
        {"대지":"결론", "내용":"중요한 결정 앞에서 하나님께 기도하자. 내 판단이 아닌 마음을 아시는 하나님의 선택을 구하자. 그 기도가 최선의 결정을 만든다", "예화_적용":"안개 속에서 지도보다 현지인 안내자가 더 필요하다. 마음을 아시는 하나님이 가장 확실한 안내자이시다"}
    ],
