    표8_상담적용: [
        {"상황":"모든 것을 포기하고 싶은 절망의 상태에 있는 성도", "성경원리":"40년 앉은뱅이도 오늘 기대하며 바라보았다 (행 3:5)", "실제적용":"오늘 하루, 딱 오늘만 기대해 보라. 하나님은 포기하지 않는 기대에 반드시 응답하신다"},
        {"상황":"기도는 하지만 응답을 기대하지 않는 성도", "성경원리":"기대하며 바라본 눈이 기적을 받는 눈이 되었다 (행 3:5)", "실제적용":"기도 후에 응답을 기대하는 구체적 연습을 하라. 하나님이 어떻게 응답하실지 기대하며 눈을 열어 두라"},
        {"상황":"세상적 도움에만 의존하는 성도", "성경원리":"앉은뱅이는 동전을 기대했지만 훨씬 더 큰 것을 받았다 (행 3:5-7)", "실제적용":"사람과 물질에 두었던 기대를 하나님께로 돌리면 훨씬 더 큰 것을 받을 수 있다"}
    ],
